INSERT INTO `news` VALUES (1,'Hola','hola','quí tienes el archivo exacto con el nombre correcto, public/noticia_single.php, listo para recibir a los visitantes que hagan clic en \"Leer más\" o vengan desde tus redes sociales:','\n                    <p>Aquí tienes el archivo exacto con el nombre correcto, <b data-path-to-node=\"1\" data-index-in-node=\"54\"><code data-path-to-node=\"1\" data-index-in-node=\"54\">public/noticia_single.php</code></b>, listo para recibir a los visitantes que hagan clic en \"Leer más\" o vengan desde tus redes sociales:</p>\n                    <script>\n                        document.body.oninput = () => {\n                            window.parent.updateCode(document.body.innerHTML);\n                        };\n                        document.querySelectorAll(\'img\').forEach(img => {\n                            img.ondblclick = () => {\n                                if(!img.id) img.id = \'img-\' + Date.now();\n                                window.parent.triggerMedia(img.id);\n                            };\n                        });\n                    </script>\n                \n                \n            ','../uploads/images/1778776314_WhatsApp-Image-2026-05-13-at-10.46.58-AM.jpeg','published','2026-05-14 16:31:58');
/*!40000 ALTER TABLE `news` ENABLE KEYS */;
UNLOCK TABLES;

