INSERT INTO `pages` VALUES (1,'Nueva Página de Impacto','nueva-pagina','published',NULL,'2026-05-14 03:51:46','2026-05-14 03:51:46'),(7,'Home','custom-page','published','<style>\n    /* =========================================\n       VARIABLES Y ESTILOS BASE\n       ========================================= */\n    :root {\n        --ah-primary: #34859B;\n        --ah-accent: #46B094;\n        --ah-dark: #0f172a;\n        --ah-text: #475569;\n        --ah-light: #f8fafc;\n    }\n\n    .ah-home-wrapper {\n        font-family: \'Inter\', sans-serif;\n        color: var(--ah-text);\n        overflow-x: hidden;\n    }\n\n    /* =========================================\n       1. CARRUSEL HERO (NIVEL PROFESIONAL)\n       ========================================= */\n    .ah-hero-slider {\n        position: relative;\n        height: 85vh;\n        min-height: 600px;\n        width: 100%;\n        overflow: hidden;\n        background: var(--ah-dark);\n    }\n\n    .ah-slide {\n        position: absolute;\n        inset: 0;\n        opacity: 0;\n        transition: opacity 0.8s ease-in-out, transform 4s ease-out;\n        transform: scale(1.05);\n        display: flex;\n        align-items: center;\n        justify-content: center;\n        text-align: center;\n        background-size: cover;\n        background-position: center;\n        z-index: 1;\n    }\n\n    .ah-slide.active {\n        opacity: 1;\n        transform: scale(1);\n        z-index: 2;\n    }\n\n    .ah-slide::before {\n        content: \'\';\n        position: absolute;\n        inset: 0;\n        background: linear-gradient(to bottom, rgba(15,23,42,0.6) 0%, rgba(52,133,155,0.8) 100%);\n        z-index: 1;\n    }\n\n    .ah-slide-content {\n        position: relative;\n        z-index: 3;\n        max-width: 900px;\n        padding: 0 20px;\n        color: white;\n        transform: translateY(20px);\n        opacity: 0;\n        transition: all 0.8s ease 0.3s;\n    }\n\n    .ah-slide.active .ah-slide-content {\n        transform: translateY(-40px); /* Subido un poco para dar espacio a las tarjetas */\n        opacity: 1;\n    }\n\n    .ah-slide-title {\n        font-size: 4rem;\n        font-weight: 800;\n        line-height: 1.1;\n        margin-bottom: 20px;\n        letter-spacing: -1px;\n    }\n\n    .ah-slide-subtitle {\n        font-size: 1.3rem;\n        font-weight: 400;\n        opacity: 0.9;\n        margin-bottom: 35px;\n        max-width: 700px;\n        margin-left: auto;\n        margin-right: auto;\n    }\n\n    .ah-btn-main {\n        display: inline-flex;\n        align-items: center;\n        gap: 10px;\n        background: var(--ah-accent);\n        color: white;\n        padding: 16px 40px;\n        border-radius: 50px;\n        font-weight: 700;\n        font-size: 1.1rem;\n        text-decoration: none;\n        transition: all 0.3s ease;\n        box-shadow: 0 10px 25px rgba(70, 176, 148, 0.4);\n    }\n\n    .ah-btn-main:hover {\n        transform: translateY(-3px);\n        background: #3eb092;\n        box-shadow: 0 15px 35px rgba(70, 176, 148, 0.5);\n    }\n\n    /* Controles del Carrusel */\n    .ah-slider-arrows {\n        position: absolute;\n        top: 50%;\n        width: 100%;\n        display: flex;\n        justify-content: space-between;\n        padding: 0 30px;\n        z-index: 10;\n        transform: translateY(-50%);\n        pointer-events: none;\n    }\n\n    .ah-arrow {\n        pointer-events: auto;\n        background: rgba(255,255,255,0.1);\n        backdrop-filter: blur(5px);\n        border: 1px solid rgba(255,255,255,0.2);\n        color: white;\n        width: 50px;\n        height: 50px;\n        border-radius: 50%;\n        display: flex;\n        align-items: center;\n        justify-content: center;\n        cursor: pointer;\n        transition: all 0.3s;\n        font-size: 1.2rem;\n    }\n\n    .ah-arrow:hover {\n        background: var(--ah-primary);\n        transform: scale(1.1);\n    }\n\n    /* =========================================\n       2. SECCIÓN DE IMPACTO (OVERLAP)\n       ========================================= */\n    .ah-impact-section {\n        position: relative;\n        z-index: 20;\n        margin-top: -100px; /* Hace que flote sobre el carrusel */\n        padding: 0 20px;\n        max-width: 1100px;\n        margin-left: auto;\n        margin-right: auto;\n    }\n\n    .ah-impact-grid {\n        display: grid;\n        grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));\n        gap: 0;\n        background: white;\n        border-radius: 20px;\n        box-shadow: 0 20px 50px rgba(0,0,0,0.1);\n        overflow: hidden;\n    }\n\n    .ah-impact-card {\n        text-align: center;\n        padding: 40px 20px;\n        border-right: 1px solid #e2e8f0;\n        transition: background 0.3s;\n    }\n    \n    .ah-impact-card:last-child { border-right: none; }\n    .ah-impact-card:hover { background: #f8fafc; }\n\n    .ah-impact-icon {\n        font-size: 2rem;\n        color: var(--ah-accent);\n        margin-bottom: 15px;\n    }\n\n    .ah-impact-number {\n        font-size: 3.5rem;\n        font-weight: 900;\n        color: var(--ah-primary);\n        line-height: 1;\n        margin-bottom: 5px;\n    }\n\n    .ah-impact-label {\n        font-weight: 700;\n        color: #64748b;\n        text-transform: uppercase;\n        letter-spacing: 1px;\n        font-size: 0.85rem;\n    }\n\n    /* =========================================\n       3. SECCIÓN INFO (SPLIT)\n       ========================================= */\n    .ah-split-section {\n        padding: 120px 20px 60px 20px;\n        max-width: 1200px;\n        margin: 0 auto;\n        display: grid;\n        grid-template-columns: 1fr 1fr;\n        gap: 60px;\n        align-items: center;\n    }\n\n    .ah-split-img {\n        position: relative;\n        border-radius: 24px;\n        overflow: hidden;\n        box-shadow: 0 30px 60px rgba(0,0,0,0.1);\n    }\n\n    .ah-split-img img {\n        width: 100%;\n        display: block;\n        transition: transform 0.5s;\n    }\n\n    .ah-split-img:hover img {\n        transform: scale(1.03);\n    }\n\n    .ah-badge {\n        display: inline-block;\n        background: rgba(70, 176, 148, 0.1);\n        color: var(--ah-accent);\n        padding: 8px 16px;\n        border-radius: 50px;\n        font-weight: 800;\n        font-size: 0.8rem;\n        text-transform: uppercase;\n        letter-spacing: 1.5px;\n        margin-bottom: 20px;\n    }\n\n    .ah-split-text h2 {\n        font-size: 2.8rem;\n        color: var(--ah-dark);\n        margin-bottom: 25px;\n        line-height: 1.2;\n        font-weight: 800;\n    }\n\n    .ah-split-text p {\n        font-size: 1.1rem;\n        line-height: 1.8;\n        margin-bottom: 20px;\n    }\n\n    /* =========================================\n       4. PILARES DE ACCIÓN\n       ========================================= */\n    .ah-pillars-section {\n        padding: 80px 20px;\n        background: var(--ah-light);\n    }\n\n    .ah-pillars-container {\n        max-width: 1200px;\n        margin: 0 auto;\n    }\n\n    .ah-section-header {\n        text-align: center;\n        margin-bottom: 70px;\n    }\n\n    .ah-section-header h2 {\n        font-size: 2.8rem;\n        color: var(--ah-dark);\n        margin-bottom: 15px;\n        font-weight: 800;\n    }\n\n    .ah-pillars-grid {\n        display: grid;\n        grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));\n        gap: 40px;\n    }\n\n    .ah-pillar-card {\n        background: white;\n        border-radius: 20px;\n        overflow: hidden;\n        border: 1px solid #e2e8f0;\n        transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);\n        display: flex;\n        flex-direction: column;\n    }\n\n    .ah-pillar-card:hover {\n        transform: translateY(-12px);\n        box-shadow: 0 30px 60px rgba(52, 133, 155, 0.12);\n        border-color: rgba(52, 133, 155, 0.3);\n    }\n\n    .ah-pillar-img {\n        height: 240px;\n        background-size: cover;\n        background-position: center;\n        position: relative;\n    }\n\n    .ah-pillar-tag {\n        position: absolute;\n        top: 20px;\n        left: 20px;\n        background: var(--ah-primary);\n        color: white;\n        padding: 6px 15px;\n        border-radius: 50px;\n        font-size: 0.8rem;\n        font-weight: 700;\n        box-shadow: 0 4px 10px rgba(0,0,0,0.2);\n    }\n\n    .ah-pillar-content {\n        padding: 35px 30px;\n        flex-grow: 1;\n        display: flex;\n        flex-direction: column;\n    }\n\n    .ah-pillar-content h3 {\n        color: var(--ah-dark);\n        margin-bottom: 15px;\n        font-size: 1.6rem;\n        font-weight: 800;\n    }\n\n    .ah-pillar-content p {\n        line-height: 1.7;\n        margin-bottom: 25px;\n        font-size: 1.05rem;\n    }\n\n    /* =========================================\n       5. LLAMADO A LA ACCIÓN (CTA)\n       ========================================= */\n    .ah-cta-section {\n        background: linear-gradient(135deg, var(--ah-primary) 0%, var(--ah-dark) 100%);\n        padding: 100px 20px;\n        text-align: center;\n        color: white;\n        position: relative;\n        overflow: hidden;\n    }\n\n    .ah-cta-content {\n        position: relative;\n        z-index: 2;\n        max-width: 700px;\n        margin: 0 auto;\n    }\n\n    .ah-cta-content h2 {\n        font-size: 3rem;\n        font-weight: 800;\n        margin-bottom: 25px;\n    }\n\n    .ah-cta-content p {\n        font-size: 1.2rem;\n        color: #cbd5e1;\n        margin-bottom: 40px;\n        line-height: 1.6;\n    }\n\n    /* =========================================\n       RESPONSIVE\n       ========================================= */\n    @media (max-width: 992px) {\n        .ah-split-section { grid-template-columns: 1fr; padding-top: 80px; }\n        .ah-slide-title { font-size: 3rem; }\n        .ah-impact-grid { grid-template-columns: 1fr 1fr; }\n        .ah-impact-card { border-bottom: 1px solid #e2e8f0; }\n        .ah-impact-card:nth-child(even) { border-right: none; }\n    }\n    @media (max-width: 768px) {\n        .ah-slide-title { font-size: 2.2rem; }\n        .ah-impact-section { margin-top: -60px; }\n        .ah-impact-number { font-size: 2.5rem; }\n    }\n</style>\n\n<div class=\"ah-home-wrapper\">\n\n    <section class=\"ah-hero-slider\" id=\"mainHeroSlider\">\n        \n        <div class=\"ah-slide\" style=\"background-image: url(\'/webah/uploads/images/banner2.jpg\');\">\n            <div class=\"ah-slide-content\">\n                <h1 class=\"ah-slide-title\">Inspirando Comunidades,<br>Creando Oportunidades.</h1>\n                <p class=\"ah-slide-subtitle\">Acompañamos a niños, familias y comunidades vulnerables mediante soluciones que promueven su desarrollo sostenible e integral.</p>\n                <a href=\"?slug=quienes-somos\" class=\"ah-btn-main\">Conoce Nuestra Historia <i class=\"fa-solid fa-arrow-right\"></i></a>\n            </div>\n        </div>\n\n        <div class=\"ah-slide active\" style=\"background-image: url(\'/webah/uploads/images/banner3.jpeg\');\">\n            <div class=\"ah-slide-content\">\n                <h1 class=\"ah-slide-title\">Liderazgo Juvenil para el Mañana</h1>\n                <p class=\"ah-slide-subtitle\">Empoderamos a las nuevas generaciones para que sean los protagonistas del cambio en sus propios municipios.</p>\n                <a href=\"?slug=noticias\" class=\"ah-btn-main\">Ver Nuestro Impacto <i class=\"fa-solid fa-arrow-right\"></i></a>\n            </div>\n        </div>\n\n        <div class=\"ah-slide\" style=\"background-image: url(\'/webah/uploads/images/banner4.jpeg\');\">\n            <div class=\"ah-slide-content\">\n                <h1 class=\"ah-slide-title\">Unidos por la Primera Infancia</h1>\n                <p class=\"ah-slide-subtitle\">Garantizamos entornos seguros y estimulantes para que los más pequeños alcancen su máximo potencial de desarrollo.</p>\n                <a href=\"?slug=contacto\" class=\"ah-btn-main\">Involúcrate Hoy <i class=\"fa-solid fa-arrow-right\"></i></a>\n            </div>\n        </div>\n\n        <div class=\"ah-slider-arrows\">\n            <div class=\"ah-arrow\" onclick=\"moveAhSlide(-1)\"><i class=\"fa-solid fa-chevron-left\"></i></div>\n            <div class=\"ah-arrow\" onclick=\"moveAhSlide(1)\"><i class=\"fa-solid fa-chevron-right\"></i></div>\n        </div>\n    </section>\n\n    <section class=\"ah-impact-section\">\n        <div class=\"ah-impact-grid\">\n            <div class=\"ah-impact-card\">\n                <i class=\"fa-solid fa-map-location-dot ah-impact-icon\"></i>\n                <div class=\"ah-impact-number\">5</div>\n                <div class=\"ah-impact-label\">Municipios de Acción</div>\n            </div>\n            <div class=\"ah-impact-card\">\n                <i class=\"fa-solid fa-users ah-impact-icon\"></i>\n                <div class=\"ah-impact-number\">340</div>\n                <div class=\"ah-impact-label\">Líderes Comunitarios</div>\n            </div>\n            <div class=\"ah-impact-card\">\n                <i class=\"fa-solid fa-hand-holding-heart ah-impact-icon\"></i>\n                <div class=\"ah-impact-number\">100%</div>\n                <div class=\"ah-impact-label\">Compromiso</div>\n            </div>\n            <div class=\"ah-impact-card\">\n                <i class=\"fa-solid fa-seedling ah-impact-icon\"></i>\n                <div class=\"ah-impact-number\">+15</div>\n                <div class=\"ah-impact-label\">Años de Experiencia</div>\n            </div>\n        </div>\n    </section>\n\n    <section class=\"ah-split-section\">\n        <div class=\"ah-split-img\">\n            <img src=\"../uploads/images/1778733130_banner.jpeg\" alt=\"Acción Honduras Equipo\" onerror=\"this.src=\'https://images.unsplash.com/photo-1593113563332-e147ce106408?auto=format&amp;fit=crop&amp;q=80&amp;w=1000\'\">\n        </div>\n        <div class=\"ah-split-text\">\n            <span class=\"ah-badge\">Propósito Social</span>\n            <h2>Transformando la realidad, juntos.</h2>\n            <p>En Acción Honduras, somos personas comprometidas que acompañamos a niños, familias y comunidades vulnerables. Construimos soluciones y conexiones humanas que promueven un desarrollo sostenible e integral desde la raíz.</p>\n            <p>Trabajamos de la mano con las comunidades de Lepaterique, Reitoca, Alubarén y Curarén para asegurar que cada acción tenga un eco de esperanza y progreso.</p>\n        </div>\n    </section>\n\n    <section class=\"ah-pillars-section\">\n        <div class=\"ah-pillars-container\">\n            <div class=\"ah-section-header\">\n                <h2>Nuestras Áreas de Acción</h2>\n                <p style=\"color: #64748b; font-size: 1.15rem; max-width: 600px; margin: 0 auto;\">Impulsamos iniciativas que transforman realidades mediante la integración, la educación y el trabajo conjunto.</p>\n            </div>\n            \n            <div class=\"ah-pillars-grid\">\n                \n                <div class=\"ah-pillar-card\">\n                    <div class=\"ah-pillar-img\" style=\"background-image: url(&quot;../uploads/images/1778783349_banner4.jpeg&quot;);\" id=\"ah-1778783345738\">\n                        <span class=\"ah-pillar-tag\">Primera Infancia</span>\n                    </div>\n                    <div class=\"ah-pillar-content\">\n                        <h3>CRECER</h3>\n                        <p>En un periodo de 3 años, los niños de 0 a 5 años incrementan sus resultados en desarrollo infantil temprano, sentando las bases para su futuro.</p>\n                    </div>\n                </div>\n\n                <div class=\"ah-pillar-card\">\n                    <div class=\"ah-pillar-img\" style=\"background-image: url(\'../uploads/images/1778767469_Gemini-Generated-Image-ccgvp4ccgvp4ccgv.png\');\">\n                        <span class=\"ah-pillar-tag\">Protección</span>\n                    </div>\n                    <div class=\"ah-pillar-content\">\n                        <h3>REDES</h3>\n                        <p>Los niños de 6 a 17 y jóvenes de 18 a 24 años conviven en entornos seguros y libres de violencia mediante el fortalecimiento de los sistemas de protección local.</p>\n                    </div>\n                </div>\n\n                <div class=\"ah-pillar-card\">\n                    <div class=\"ah-pillar-img\" style=\"background-image: url(\'https://images.unsplash.com/photo-1542601906990-b4d3fb778b09?auto=format&amp;fit=crop&amp;q=80&amp;w=800\');\">\n                        <span class=\"ah-pillar-tag\">Medios de Vida</span>\n                    </div>\n                    <div class=\"ah-pillar-content\">\n                        <h3>Tejiendo mi Futuro</h3>\n                        <p>Incrementamos las competencias para acceder a medios de vida a través de empleo digno o emprendimiento para jóvenes de 18 a 24 años.</p>\n                    </div>\n                </div>\n\n            </div>\n        </div>\n    </section>\n\n    <section class=\"ah-cta-section\">\n        <div class=\"ah-cta-content\">\n            <h2>Únete a nuestra misión</h2>\n            <p>La verdadera transformación requiere de participación, innovación y trabajo en equipo. Sé parte del cambio y deja tu huella en nuestras comunidades.</p>\n            <a href=\"?slug=contacto\" class=\"ah-btn-main\" style=\"background: white; color: var(--ah-dark); box-shadow: 0 10px 30px rgba(0,0,0,0.2);\">Contáctanos Hoy</a>\n        </div>\n    </section>\n\n</div>','2026-05-14 04:22:17','2026-05-14 18:29:11'),(14,'Nuestra Historia','nuestra-historia','published','<section class=\"home-hero\" style=\"background-image: url(&quot;../uploads/images/1778736625_IMG-20260323-110221.jpg&quot;); padding: 100px 20px; text-align: center; color: white; background-size: cover; background-position: center 38%; font-size: 20px;\" id=\"ah-1778736522683\">\n  <h1 style=\"font-size: 3.5rem;\" data-qb-tmp-id=\"lt-634390\" spellcheck=\"false\" data-gramm=\"false\" data-lpop-hide-native-caret=\"\">Nuestra Historia</h1>\n  <p>Descripción del bloque hero aquí.</p>\n</section>\n\n                    \n                    \n                \n                \n            <lpop-new-container data-lpop-os=\"Windows\" spellcheck=\"false\" data-lpop-adapter-name=\"contenteditable\" data-lpop-theme=\"green\" data-lpop-circle-position=\"bottom\" data-lpop-size=\"large\" style=\"--lpop-new-theme-color: #008847; --lpop-original-caret-color: rgb(255, 255, 255); --lpop-brand-icon: url(chrome-extension://iidnbdjijdkbmajdffnidomddglmieko/assets/images/toolbox/contextual-cursor-icon.svg); left: 682.788px !important; top: 161.6px !important; height: 68px !important;\"><lpop-new-circle></lpop-new-circle><lpop-new-pill-container><lpop-new-dilation-label></lpop-new-dilation-label><lpop-new-contextual-home-container></lpop-new-contextual-home-container></lpop-new-pill-container><lpop-new-tooltip popover=\"manual\"><lt-span class=\"lt-lpop__tooltip\">AI Tools <lt-span class=\"lt-lpop__tooltip__hint\">(ctrl ×2)</lt-span></lt-span></lpop-new-tooltip></lpop-new-container><qb-toolbar id=\"qb-toolbar-container\" style=\"display: none;\"><qb-div class=\"qb-toolbar__wrapper\" style=\"left: 876px; position: absolute !important; top: 215px !important; bottom: auto !important; z-index: auto; opacity: 1 !important; pointer-events: all !important;\"><div style=\"all: initial !important;\"><qb-div style=\"all: initial !important;\"></qb-div></div></qb-div></qb-toolbar>\n\n\n                    \n                    \n                \n                \n            <lpop-new-container data-lpop-os=\"Windows\" spellcheck=\"false\" data-lpop-adapter-name=\"contenteditable\" data-lpop-theme=\"green\" data-lpop-circle-position=\"bottom\" style=\"--lpop-new-theme-color: #008847; --lpop-original-caret-color: rgb(0, 0, 0); --lpop-brand-icon: url(chrome-extension://iidnbdjijdkbmajdffnidomddglmieko/assets/images/toolbox/contextual-cursor-icon.svg); left: 222.15px !important; top: 404.125px !important; height: 19.2px !important;\"><lpop-new-circle></lpop-new-circle><lpop-new-pill-container><lpop-new-dilation-label></lpop-new-dilation-label><lpop-new-contextual-home-container></lpop-new-contextual-home-container></lpop-new-pill-container><lpop-new-tooltip popover=\"manual\"><lt-span class=\"lt-lpop__tooltip\">AI Tools <lt-span class=\"lt-lpop__tooltip__hint\">(ctrl ×2)</lt-span></lt-span></lpop-new-tooltip></lpop-new-container><qb-toolbar id=\"qb-toolbar-container\" style=\"display: none;\"><qb-div class=\"qb-toolbar__wrapper qb-toolbar--small\" style=\"left: 807px; position: absolute !important; top: 1322px !important; bottom: auto !important; z-index: auto; opacity: 1 !important; pointer-events: all !important;\"><div style=\"all: initial !important;\"><qb-div style=\"all: initial !important;\"></qb-div></div></qb-div></qb-toolbar>\n<section style=\"padding: 40px 20px; max-width: 800px; margin: 0 auto; text-align: center;\">\n  <h2>Subtítulo Informativo</h2>\n  <p data-listener-added_b52ff668=\"true\" data-qb-tmp-id=\"lt-938962\" spellcheck=\"false\" data-gramm=\"false\" data-listener-added_42dc8970=\"true\"></p><div style=\"text-align: left;\"><br></div><p></p>\n\n\n\n\n\n<p data-qb-tmp-id=\"lt-381190\" spellcheck=\"false\" data-gramm=\"false\" data-listener-added_42dc8970=\"true\" style=\"line-height: 2;\"></p><p class=\"MsoNormal\" style=\"margin-top:0cm;margin-right:5.65pt;margin-bottom:\n0cm;margin-left:0cm;text-align:justify;line-height:normal\"><span style=\"font-size: 12pt; color: black; line-height: 32px;\">Acción Honduras, es una institución no gubernamental de\ndesarrollo, de carácter social, sin fines de lucro, con <a name=\"_Hlk229387152\" style=\"font-size: 16px;\">Personería\nJurídica 372-2005, bajo expediente de Reforma de Estatutos PJ-12082019-2578</a>.\nAH es una organización que tiene su sede en el municipio de Lepaterique del\ndepartamento de Francisco Morarán, con ámbito o cobertura a nivel nacional,\ncomo se muestra en el siguiente mapa, focalizada en los departamentos\nsombreados. pero no excluyente de otros departamentos.<o:p></o:p></span></p>\n\n<p class=\"MsoNormal\" align=\"center\" style=\"margin: 5pt 5.65pt 0cm 0cm;\"><span style=\"font-size:\n12.0pt;line-height:106%;mso-fareast-font-family:Arial;mso-bidi-font-family:\nCalibri;color:black\"><!--[if gte vml 1]><v:shapetype id=\"_x0000_t75\"\n coordsize=\"21600,21600\" o:spt=\"75\" o:preferrelative=\"t\" path=\"m@4@5l@4@11@9@11@9@5xe\"\n filled=\"f\" stroked=\"f\">\n <v:stroke joinstyle=\"miter\"/>\n <v:formulas>\n  <v:f eqn=\"if lineDrawn pixelLineWidth 0\"/>\n  <v:f eqn=\"sum @0 1 0\"/>\n  <v:f eqn=\"sum 0 0 @1\"/>\n  <v:f eqn=\"prod @2 1 2\"/>\n  <v:f eqn=\"prod @3 21600 pixelWidth\"/>\n  <v:f eqn=\"prod @3 21600 pixelHeight\"/>\n  <v:f eqn=\"sum @0 0 1\"/>\n  <v:f eqn=\"prod @6 1 2\"/>\n  <v:f eqn=\"prod @7 21600 pixelWidth\"/>\n  <v:f eqn=\"sum @8 21600 0\"/>\n  <v:f eqn=\"prod @7 21600 pixelHeight\"/>\n  <v:f eqn=\"sum @10 21600 0\"/>\n </v:formulas>\n <v:path o:extrusionok=\"f\" gradientshapeok=\"t\" o:connecttype=\"rect\"/>\n <o:lock v:ext=\"edit\" aspectratio=\"t\"/>\n</v:shapetype><v:shape id=\"Picture_x0020_1\" o:spid=\"_x0000_i1025\" type=\"#_x0000_t75\"\n style=\'width:324pt;height:205.2pt;mso-position-horizontal-relative:page;\n mso-position-vertical-relative:page\'>\n <v:fill o:detectmouseclick=\"t\"/>\n <v:imagedata src=\"file:///C:/Users/fabri/AppData/Local/Temp/msohtmlclip1/01/clip_image001.png\"\n  o:title=\"\"/>\n</v:shape><![endif]--><!--[if !vml]--><img width=\"432\" height=\"274\" src=\"data:image/png;base64,\" v:shapes=\"Picture_x0020_1\"><!--[endif]--><o:p></o:p></span></p>\n\n<p class=\"MsoNormal\" style=\"margin-top:0cm;margin-right:5.65pt;margin-bottom:\n0cm;margin-left:0cm;text-align:justify;line-height:normal\"><br></p>\n\n<p class=\"MsoNormal\" style=\"margin-top:5.0pt;margin-right:5.65pt;margin-bottom:\n0cm;margin-left:0cm;text-align:justify\"><span style=\"font-size:12.0pt;\nline-height:106%;mso-fareast-font-family:Arial;mso-bidi-font-family:Calibri;\ncolor:black\">Surgida en el año 2018 de la fusión de dos organizaciones\nsociales, la Asociación de Desarrollo del Área de Lepaterique (ADAL) y la\nAsociación de Desarrollo de Área Curarén, Alubarén y Reitoca (ADACAR)\n-organizaciones con un importante reconocimiento comunitario y un abordaje\nsimilar en áreas temáticas y geográficas desde el 2005- AH ha logrado\ncapitalizar el prestigio y patrimonio humano de ambas organizaciones. <o:p></o:p></span></p>\n\n<p class=\"MsoNormal\" style=\"margin-top:5.0pt;margin-right:5.65pt;margin-bottom:\n0cm;margin-left:0cm;text-align:justify\"><span style=\"font-size:12.0pt;\nline-height:106%;mso-fareast-font-family:Arial;mso-bidi-font-family:Calibri;\ncolor:black\">Actualmente AH tiene varios asocios o alianzas estratégicas con\norganizaciones en los sectores público y privado nacional e internacional, con\nconocimiento, dominio y operatividad temática que aborda, facilita y apoya\ninstitucionalmente siguientes: </span><span style=\"font-size:14.0pt;line-height:\n106%;mso-fareast-font-family:Arial;mso-bidi-font-family:Calibri;color:black\">&nbsp;</span><span style=\"font-size:12.0pt;\nline-height:106%;mso-fareast-font-family:Arial;mso-bidi-font-family:Calibri;\ncolor:black\">desarrollo económico, seguridad alimentaria y nutricional,\nempleabilidad, emprendedurismo, medios de vida, patrocinio, rol que juegan los\ncuidadores, cambio climático, resiliencia, enfoques de gestión de riesgos,\nderechos y género, salud, educación, prevención de riesgos y desastres,\ncoherentes con la prioridad y asocios establecidos y por establecer,\nrespondiendo y orientados a contribuir al logro de los Objetivos de Desarrollo\nSostenible (ODS) de la Agenda 2030 del Sistema de las Naciones Unidas.\nRecientes asocios institucionales con el Programa Mundial de Alimentos (PMA),\nFondo Global para la Infancia, FOCUS, Comité de Rescate Internacional, Orden de\nMalta, UNICEF, otras como ser organizaciones multilaterales como el PNUD, FAO,\nbilaterales, filantropía y con agencias de cooperación técnica y financiera\ninternacional.<b> <o:p></o:p></b></span></p><p></p>\n<span id=\"monica-writing-entry-btn-root\" style=\"position: absolute; left: 0px; top: 0px; pointer-events: none;\"></span></section>\n\n        \n\n        \n    \n    \n<qb-toolbar id=\"qb-toolbar-container\" style=\"display: none;\"><qb-div class=\"qb-toolbar__wrapper\" style=\"left: 807px; position: fixed !important; top: auto !important; bottom: 12px !important; opacity: 1 !important; pointer-events: all !important; z-index: auto;\"><div style=\"all: initial !important;\"><qb-div style=\"all: initial !important;\"></qb-div></div></qb-div></qb-toolbar><qb-toolbar id=\"qb-toolbar-container\" style=\"display: none;\"><qb-div class=\"qb-toolbar__wrapper qb-toolbar__wrapper--hide\"><div style=\"all: initial !important;\"><qb-div style=\"all: initial !important;\"></qb-div></div></qb-div></qb-toolbar>\n        \n\n        \n    \n    \n<qb-toolbar id=\"qb-toolbar-container\" style=\"display: none;\"><qb-div class=\"qb-toolbar__wrapper\" style=\"left: 807px; position: absolute !important; top: 397px !important; bottom: auto !important; z-index: auto; opacity: 1 !important; pointer-events: all !important;\"><div style=\"all: initial !important;\"><qb-div style=\"all: initial !important;\"></qb-div></div></qb-div></qb-toolbar><qb-toolbar id=\"qb-toolbar-container\" style=\"display: none;\"><qb-div class=\"qb-toolbar__wrapper\" style=\"left: 807px; position: fixed !important; top: auto !important; bottom: 12px !important; z-index: auto; opacity: 1 !important; pointer-events: all !important;\"><div style=\"all: initial !important;\"><qb-div style=\"all: initial !important;\"></qb-div></div></qb-div></qb-toolbar>','2026-05-14 05:09:09','2026-05-14 13:52:22'),(15,'Noticias','noticias','published','<section class=\"layout-block\" id=\"ah-news-module\" style=\"padding: 60px 20px; max-width: 1200px; margin: 0 auto;\">\n    \n    <div style=\"text-align: center; margin-bottom: 40px;\">\n        <h2 style=\"color: #1e293b; font-size: 2.5rem; font-weight: 800; margin-bottom: 15px;\">Últimas Noticias</h2>\n        <p style=\"color: #64748b; font-size: 1.1rem;\">Impacto y actualidad en nuestras comunidades.</p>\n    </div>\n\n    <style>\n        .ah-news-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(320px, 1fr)); gap: 40px; }\n        .ah-news-card { background: #fff; border-radius: 16px; overflow: hidden; box-shadow: 0 10px 30px rgba(0,0,0,0.06); transition: all 0.3s; display: flex; flex-direction: column; border: 1px solid #f1f5f9; text-decoration: none; }\n        .ah-news-card:hover { transform: translateY(-8px); box-shadow: 0 20px 40px rgba(52,133,155,0.15); }\n        .ah-news-img-box { width: 100%; height: 220px; position: relative; overflow: hidden; }\n        .ah-news-img-box img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.5s; }\n        .ah-news-card:hover .ah-news-img-box img { transform: scale(1.05); }\n        .ah-news-badge { position: absolute; bottom: 15px; left: 15px; background: #46B094; color: white; padding: 6px 12px; border-radius: 50px; font-size: 0.75rem; font-weight: bold; }\n        .ah-news-body { padding: 30px 25px; flex-grow: 1; display: flex; flex-direction: column; }\n        .ah-news-title { font-size: 1.3rem; color: #1e293b; margin-bottom: 15px; font-weight: 800; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }\n        .ah-news-desc { color: #64748b; font-size: 0.95rem; line-height: 1.6; margin-bottom: 25px; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }\n        .ah-news-footer { margin-top: auto; color: #34859B; font-weight: bold; font-size: 0.9rem; }\n        \n        .ah-pagination { display: flex; justify-content: center; gap: 8px; margin-top: 50px; }\n        .ah-page-btn { padding: 10px 15px; border-radius: 8px; background: white; color: #64748b; border: 1px solid #e2e8f0; cursor: pointer; font-weight: bold; transition: 0.2s; }\n        .ah-page-btn:hover:not(:disabled) { background: #34859B; color: white; border-color: #34859B; }\n        .ah-page-btn.active { background: #34859B; color: white; border-color: #34859B; }\n        .ah-page-btn:disabled { opacity: 0.5; cursor: not-allowed; }\n    </style>\n\n    <div id=\"ah-news-feed\" class=\"ah-news-grid\">\n        <div style=\"text-align:center; grid-column: 1 / -1; padding: 40px; color:#94a3b8;\">\n            <i class=\"fa-solid fa-circle-notch fa-spin\" style=\"font-size: 2rem;\"></i> Cargando noticias...\n        </div>\n    </div>\n    \n    <div id=\"ah-news-pagination\" class=\"ah-pagination\"></div>\n\n    <script>\n        (function() {\n            const feedContainer = document.getElementById(\'ah-news-feed\');\n            const pagContainer = document.getElementById(\'ah-news-pagination\');\n            \n            // Función para cargar noticias de la API\n            async function fetchNews(page = 1) {\n                feedContainer.innerHTML = \'<div style=\"text-align:center; grid-column: 1 / -1; padding: 40px; color:#94a3b8;\"><i class=\"fa-solid fa-spinner fa-spin\" style=\"font-size: 2rem;\"></i><br>Cargando...</div>\';\n                \n                try {\n                    const response = await fetch(\'../api/get_news.php?p=\' + page);\n                    const result = await response.json();\n                    \n                    if(result.success && result.data.length > 0) {\n                        renderNews(result.data);\n                        renderPagination(result.pagination);\n                    } else {\n                        feedContainer.innerHTML = \'<div style=\"text-align:center; grid-column: 1 / -1; color:#94a3b8;\">No hay noticias publicadas aún.</div>\';\n                        pagContainer.innerHTML = \'\';\n                    }\n                } catch (error) {\n                    feedContainer.innerHTML = \'<div style=\"text-align:center; grid-column: 1 / -1; color:#ef4444;\">Error al cargar las noticias.</div>\';\n                }\n            }\n\n            // Función para pintar el HTML de las tarjetas\n            function renderNews(newsArray) {\n                feedContainer.innerHTML = newsArray.map(n => `\n                    <a href=\"noticia_single.php?slug=${n.slug}\" class=\"ah-news-card\" contenteditable=\"false\">\n                        <div class=\"ah-news-img-box\">\n                            <img src=\"${n.cover_image}\" alt=\"${n.title}\">\n                            <div class=\"ah-news-badge\">${n.fecha_formateada}</div>\n                        </div>\n                        <div class=\"ah-news-body\">\n                            <h3 class=\"ah-news-title\">${n.title}</h3>\n                            <p class=\"ah-news-desc\">${n.excerpt}</p>\n                            <div class=\"ah-news-footer\">Leer artículo <i class=\"fa-solid fa-arrow-right\"></i></div>\n                        </div>\n                    </a>\n                `).join(\'\');\n            }\n\n            // Función para pintar los botones de paginación\n            function renderPagination(pag) {\n                if (pag.total_pages <= 1) {\n                    pagContainer.innerHTML = \'\';\n                    return;\n                }\n\n                let html = `<button class=\"ah-page-btn\" ${pag.current === 1 ? \'disabled\' : \'\'} onclick=\"window.ahLoadNews(${pag.current - 1})\"><i class=\"fa-solid fa-chevron-left\"></i></button>`;\n                \n                for(let i = 1; i <= pag.total_pages; i++) {\n                    html += `<button class=\"ah-page-btn ${pag.current === i ? \'active\' : \'\'}\" onclick=\"window.ahLoadNews(${i})\">${i}</button>`;\n                }\n\n                html += `<button class=\"ah-page-btn\" ${pag.current === pag.total_pages ? \'disabled\' : \'\'} onclick=\"window.ahLoadNews(${pag.current + 1})\"><i class=\"fa-solid fa-chevron-right\"></i></button>`;\n                \n                pagContainer.innerHTML = html;\n            }\n\n            // Exponer la función globalmente para que los botones la puedan usar\n            window.ahLoadNews = fetchNews;\n\n            // Cargar la primera página al iniciar\n            fetchNews(1);\n        })();\n    </script>\n</section>','2026-05-14 16:32:13','2026-05-14 16:44:02'),(16,'Noticia','noticia','published','<section class=\"layout-block\" id=\"ah-news-module\" style=\"padding: 60px 20px; max-width: 1200px; margin: 0 auto;\">\n    \n    <div style=\"text-align: center; margin-bottom: 40px;\">\n        <h2 style=\"color: #1e293b; font-size: 2.5rem; font-weight: 800; margin-bottom: 15px;\">Últimas Noticias</h2>\n        <p style=\"color: #64748b; font-size: 1.1rem;\">Impacto y actualidad en nuestras comunidades.</p>\n    </div>\n\n    <style>\n        .ah-news-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(320px, 1fr)); gap: 40px; }\n        .ah-news-card { background: #fff; border-radius: 16px; overflow: hidden; box-shadow: 0 10px 30px rgba(0,0,0,0.06); transition: all 0.3s; display: flex; flex-direction: column; border: 1px solid #f1f5f9; text-decoration: none; }\n        .ah-news-card:hover { transform: translateY(-8px); box-shadow: 0 20px 40px rgba(52,133,155,0.15); }\n        .ah-news-img-box { width: 100%; height: 220px; position: relative; overflow: hidden; }\n        .ah-news-img-box img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.5s; }\n        .ah-news-card:hover .ah-news-img-box img { transform: scale(1.05); }\n        .ah-news-badge { position: absolute; bottom: 15px; left: 15px; background: #46B094; color: white; padding: 6px 12px; border-radius: 50px; font-size: 0.75rem; font-weight: bold; }\n        .ah-news-body { padding: 30px 25px; flex-grow: 1; display: flex; flex-direction: column; }\n        .ah-news-title { font-size: 1.3rem; color: #1e293b; margin-bottom: 15px; font-weight: 800; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }\n        .ah-news-desc { color: #64748b; font-size: 0.95rem; line-height: 1.6; margin-bottom: 25px; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }\n        .ah-news-footer { margin-top: auto; color: #34859B; font-weight: bold; font-size: 0.9rem; }\n        \n        .ah-pagination { display: flex; justify-content: center; gap: 8px; margin-top: 50px; }\n        .ah-page-btn { padding: 10px 15px; border-radius: 8px; background: white; color: #64748b; border: 1px solid #e2e8f0; cursor: pointer; font-weight: bold; transition: 0.2s; }\n        .ah-page-btn:hover:not(:disabled) { background: #34859B; color: white; border-color: #34859B; }\n        .ah-page-btn.active { background: #34859B; color: white; border-color: #34859B; }\n        .ah-page-btn:disabled { opacity: 0.5; cursor: not-allowed; }\n    </style>\n\n    <div id=\"ah-news-feed\" class=\"ah-news-grid\">\n        <div style=\"text-align:center; grid-column: 1 / -1; padding: 40px; color:#94a3b8;\">\n            <i class=\"fa-solid fa-circle-notch fa-spin\" style=\"font-size: 2rem;\"></i> Cargando noticias...\n        </div>\n    </div>\n    \n    <div id=\"ah-news-pagination\" class=\"ah-pagination\"></div>\n\n    <script>\n        (function() {\n            const feedContainer = document.getElementById(\'ah-news-feed\');\n            const pagContainer = document.getElementById(\'ah-news-pagination\');\n            \n            // Función para cargar noticias de la API\n            async function fetchNews(page = 1) {\n                feedContainer.innerHTML = \'<div style=\"text-align:center; grid-column: 1 / -1; padding: 40px; color:#94a3b8;\"><i class=\"fa-solid fa-spinner fa-spin\" style=\"font-size: 2rem;\"></i><br>Cargando...</div>\';\n                \n                try {\n                    const response = await fetch(\'../api/get_news.php?p=\' + page);\n                    const result = await response.json();\n                    \n                    if(result.success && result.data.length > 0) {\n                        renderNews(result.data);\n                        renderPagination(result.pagination);\n                    } else {\n                        feedContainer.innerHTML = \'<div style=\"text-align:center; grid-column: 1 / -1; color:#94a3b8;\">No hay noticias publicadas aún.</div>\';\n                        pagContainer.innerHTML = \'\';\n                    }\n                } catch (error) {\n                    feedContainer.innerHTML = \'<div style=\"text-align:center; grid-column: 1 / -1; color:#ef4444;\">Error al cargar las noticias.</div>\';\n                }\n            }\n\n            // Función para pintar el HTML de las tarjetas\n            function renderNews(newsArray) {\n                feedContainer.innerHTML = newsArray.map(n => `\n                    <a href=\"noticia_single.php?slug=${n.slug}\" class=\"ah-news-card\" contenteditable=\"false\">\n                        <div class=\"ah-news-img-box\">\n                            <img src=\"${n.cover_image}\" alt=\"${n.title}\">\n                            <div class=\"ah-news-badge\">${n.fecha_formateada}</div>\n                        </div>\n                        <div class=\"ah-news-body\">\n                            <h3 class=\"ah-news-title\">${n.title}</h3>\n                            <p class=\"ah-news-desc\">${n.excerpt}</p>\n                            <div class=\"ah-news-footer\">Leer artículo <i class=\"fa-solid fa-arrow-right\"></i></div>\n                        </div>\n                    </a>\n                `).join(\'\');\n            }\n\n            // Función para pintar los botones de paginación\n            function renderPagination(pag) {\n                if (pag.total_pages <= 1) {\n                    pagContainer.innerHTML = \'\';\n                    return;\n                }\n\n                let html = `<button class=\"ah-page-btn\" ${pag.current === 1 ? \'disabled\' : \'\'} onclick=\"window.ahLoadNews(${pag.current - 1})\"><i class=\"fa-solid fa-chevron-left\"></i></button>`;\n                \n                for(let i = 1; i <= pag.total_pages; i++) {\n                    html += `<button class=\"ah-page-btn ${pag.current === i ? \'active\' : \'\'}\" onclick=\"window.ahLoadNews(${i})\">${i}</button>`;\n                }\n\n                html += `<button class=\"ah-page-btn\" ${pag.current === pag.total_pages ? \'disabled\' : \'\'} onclick=\"window.ahLoadNews(${pag.current + 1})\"><i class=\"fa-solid fa-chevron-right\"></i></button>`;\n                \n                pagContainer.innerHTML = html;\n            }\n\n            // Exponer la función globalmente para que los botones la puedan usar\n            window.ahLoadNews = fetchNews;\n\n            // Cargar la primera página al iniciar\n            fetchNews(1);\n        })();\n    </script>\n</section>','2026-05-14 20:10:22','2026-05-14 20:11:56');
